import{_ as r,a as t}from"./chunks/compare-tempsweep.B68yRgr8.js";import{_ as a,o as s,c as o,ag as l}from"./chunks/framework.DqVSm8kp.js";const h=JSON.parse('{"title":"Comparer","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/compare.md","filePath":"fr/guide/compare.md"}'),i={name:"fr/guide/compare.md"};function n(u,e,d,p,m,c){return s(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="comparer" tabindex="-1">Comparer <a class="header-anchor" href="#comparer" aria-label="Permalink to &quot;Comparer&quot;">​</a></h1><p>La page Comparer vous permet d&#39;executer le meme prompt a travers plusieurs modeles ou configurations simultanement et de comparer les resultats cote a cote.</p><p><strong>Element de la barre laterale :</strong> Comparer <strong>Route :</strong> <code>/compare</code></p><p><img src="'+r+'" alt="Comparaison cote a cote"></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page comporte une zone de saisie de prompt en haut et une grille configurable de <strong>slots</strong> en dessous. Chaque slot represente une combinaison modele/parametres.</p><h2 id="configurer-les-slots" tabindex="-1">Configurer les slots <a class="header-anchor" href="#configurer-les-slots" aria-label="Permalink to &quot;Configurer les slots&quot;">​</a></h2><ol><li>Cliquez sur <strong>Ajouter un slot</strong> pour creer un slot de comparaison (jusqu&#39;a 4 slots).</li><li>Pour chaque slot, configurez : <ul><li><strong>Modele</strong> -- Selectionnez parmi vos modeles Ollama installes (les modeles d&#39;embedding sont filtres)</li><li><strong>Temperature</strong> -- Controle l&#39;aleatoire (0 = deterministe, plus eleve = plus creatif)</li><li><strong>Prompt systeme</strong> -- Instructions optionnelles au niveau systeme</li><li><strong>Parametres d&#39;echantillonnage</strong> -- Top-k, top-p, seed et autres options Ollama</li></ul></li></ol><p>Chaque slot affiche ses parametres sous forme de pastilles pour une reference rapide.</p><h2 id="lancer-une-comparaison" tabindex="-1">Lancer une comparaison <a class="header-anchor" href="#lancer-une-comparaison" aria-label="Permalink to &quot;Lancer une comparaison&quot;">​</a></h2><ol><li>Saisissez votre prompt dans la zone de saisie partagee.</li><li>Cliquez sur <strong>Lancer tout</strong>. Tous les slots diffusent leurs reponses simultanement.</li><li>Observez les resultats apparaitre cote a cote en temps reel.</li></ol><h2 id="vues" tabindex="-1">Vues <a class="header-anchor" href="#vues" aria-label="Permalink to &quot;Vues&quot;">​</a></h2><h3 id="vue-grille" tabindex="-1">Vue grille <a class="header-anchor" href="#vue-grille" aria-label="Permalink to &quot;Vue grille&quot;">​</a></h3><p>La vue par defaut. Tous les slots affichent leurs resultats en streaming dans une disposition en grille. Chaque slot montre :</p><ul><li>La reponse du modele</li><li>Une pastille de parametres indiquant le nom du modele et la temperature</li></ul><h3 id="vue-diff" tabindex="-1">Vue diff <a class="header-anchor" href="#vue-diff" aria-label="Permalink to &quot;Vue diff&quot;">​</a></h3><p>Passez en vue diff pour voir le <strong>surlignage mot par mot</strong> des differences entre deux sorties. Le texte ajoute est surligne en vert, le texte supprime en rouge.</p><p><img src="'+t+'" alt="Balayage de temperature"></p><h2 id="barre-de-metriques" tabindex="-1">Barre de metriques <a class="header-anchor" href="#barre-de-metriques" aria-label="Permalink to &quot;Barre de metriques&quot;">​</a></h2><p>Sous la grille, une <strong>barre de metriques</strong> visuelle compare les indicateurs cles de performance entre tous les slots :</p><table tabindex="0"><thead><tr><th>Metrique</th><th>Description</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>Time to first token -- rapidite de debut de reponse de chaque modele</td></tr><tr><td><strong>Tokens/sec</strong></td><td>Debit de generation</td></tr><tr><td><strong>Total tokens</strong></td><td>Nombre de tokens de completion</td></tr></tbody></table><h2 id="presets-rapides" tabindex="-1">Presets rapides <a class="header-anchor" href="#presets-rapides" aria-label="Permalink to &quot;Presets rapides&quot;">​</a></h2><p>Des presets en un clic pour configurer des scenarios de comparaison courants :</p><ul><li><strong>Balayage de temperature</strong> -- Meme modele a 3 temperatures differentes (0.2, 0.7, 1.2) pour observer l&#39;evolution de la creativite</li><li><strong>Paire deterministe</strong> -- Meme modele, meme seed, memes parametres -- verifie la reproductibilite</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Meme modele, parametres differents</strong> est souvent plus instructif que comparer des modeles differents. Essayez de varier la temperature ou les prompts systeme.</li><li><strong>Les slots persistent</strong> lors de la navigation entre les pages durant la session.</li><li>Utilisez un prompt a <strong>faible nombre de tokens</strong> pour des iterations rapides.</li></ul>',26)])])}const b=a(i,[["render",n]]);export{h as __pageData,b as default};
